 @Test public void completeSourceHealAndReinforcementRenderEveryPixelAtActorFootWithoutMatte()throws Exception{
  ClassicSkillReference ref=new ClassicSkillReference(m.h.c);Bitmap grid=Bitmap.createBitmap(1280,660,Bitmap.Config.ARGB_8888);Canvas gc=new Canvas(grid);gc.drawColor(0xff3e443e);int row=0;
  for(String id:new String[]{"SK_공통_010","SK_마법사_044","SK_마법사_006"}){ClassicSkillReference.Channel ch=ref.channel(id,false);CapturedSkillFx.Sequence q=ch.sequence;assertEquals(0f,q.footOffsetY,0);assertNull(ref.mageDisplayAtlas(ch));int elapsed=0;
   for(int n=0;n<q.durations.length;n++){Bitmap actual=Bitmap.createBitmap(600,600,Bitmap.Config.ARGB_8888),expected=actual.copy(Bitmap.Config.ARGB_8888,true);actual.eraseColor(0xff383e38);expected.eraseColor(0xff383e38);ref.draw(new Canvas(actual),ch,(elapsed+1)/1000f,300,300);Paint p=new Paint();p.setFilterBitmap(false);p.setXfermode(q.normalBlend?null:new PorterDuffXfermode(q.additiveBlend?PorterDuff.Mode.ADD:PorterDuff.Mode.SCREEN));int sx=n%q.columns*q.width,sy=n/q.columns*q.height;new Canvas(expected).drawBitmap(q.atlas,new Rect(sx,sy,sx+q.width,sy+q.height),new RectF(300-q.pivotX,300-q.pivotY,300+q.width-q.pivotX,300+q.height-q.pivotY),p);assertTrue(id+" frame"+n,actual.sameAs(expected));elapsed+=q.durations[n];actual.recycle();expected.recycle();}
   for(int n=0;n<8;n++)ref.draw(gc,ch,q.duration*n/8,80+n*160,180+row*210);row++;
  }RogueRepairV232Test.save(grid,"v249-complete-source-registered-grid");
 }
 @Test public void allFourKurotoIdsHealThroughNormalQuickslotsAndShareIdenticalOriginalSequence()throws Exception{
  ClassicSkillReference ref=new ClassicSkillReference(m.h.c);for(String id:new String[]{"SK_공통_010","SK_무도가_032","SK_성직자_058","SK_마법사_056"}){m.setup();GameView v=m.actor(id);RuntimeState s=m.h.field(v,"state");String job=SkillAbilityCatalog.get(id).job;s.rpg().restoreJobCode(job.equals("무도가")?"MARTIAL_ARTIST":job.equals("성직자")?"CLERIC":"MAGE");s.player().hp=1000;int mp=s.player().mp;m.tap(v);m.contact(v);assertTrue(id,s.player().hp>1000);assertEquals(mp-((RuntimeCombatSession)m.h.field(v,"combatSession")).effectiveMpCost(id),s.player().mp);ClassicSkillReference.Channel ch=ref.channel(id,false);assertEquals(ref.channel("SK_공통_010",false).sequence.atlas,ch.sequence.atlas);m.h.capture(v,"v249-heal-"+id);}
 }
 @Test public void reinforcementUsesNormalSelfCastAndConfusionStarsStopAfterOneSequenceWhileDebuffRemains()throws Exception{
  GameView v=m.actor("SK_마법사_044");RuntimeState s=m.h.field(v,"state");m.tap(v);m.contact(v);assertTrue(s.skillEffects().has("player","ELEMENT_BOOST"));m.h.capture(v,"v249-reinforcement");m.setup();v=m.actor("SK_마법사_006");s=m.h.field(v,"state");m.tap(v);m.contact(v);RuntimeState.Monster target=s.monsters().get(0);assertTrue(s.skillEffects().has(target.id,"AMNESIA"));SkillVfxRenderer fx=m.h.field(v,"skillVfx");assertEquals(1,fx.pulses.stream().filter(p->!p.caster&&p.id.equals("SK_마법사_006")).count());m.h.capture(v,"v249-confusion-once");fx.tick(2);assertEquals(0,fx.pulses.size());assertTrue(s.skillEffects().has(target.id,"AGGRO_RESET"));
 }
 @Test public void confusionEnablesRealSneakAndAmbushWithDoubleHpPopupAndLedgerThenExpires()throws Exception{
  RogueCombatV234Test h=new RogueCombatV234Test();h.setup();RuntimeState s=h.state();RuntimeState.Monster target=h.add(s,"front",32,16);RuntimeCombatSession c=h.session(s,CharacterRenderer.Direction.SE);assertTrue(c.submitPlayer(target.id,"SK_마법사_006").accepted());c.tick(c.effectiveCastSeconds("SK_마법사_006")+.01f);assertEquals(10,s.skillEffects().get(target.id,"AMNESIA").remaining,0);RuntimeCombatPortAdapter port=m.h.field(c,"port");port.abilities.random=()->.99;
  for(String id:new String[]{"SK_도적_015","SK_도적_023"}){assertNull(port.abilities.ready("player",target.id,id,true));int before=target.hp;CombatResolver.EffectResult hit=port.applyDamage("player",target.id,id,123);assertEquals(246,before-target.hp);assertEquals(246,hit.appliedAmount);assertEquals(246,target.lastDamage);assertTrue(s.skillEffects().has(target.id,"AGGRO_RESET"));}
  s.tick(10.01f);assertFalse(s.skillEffects().has(target.id,"AMNESIA"));int before=target.hp;s.damage(target,123);assertEquals(123,before-target.hp);
 }
 @Test public void persistentSleepAndPoisonFollowActualTargetAndClearOnWakeCureExpiryOrDeath()throws Exception{
  for(String id:new String[]{"SK_마법사_017","SK_마법사_012"}){m.setup();GameView v=m.actor(id);RuntimeState s=m.h.field(v,"state");RuntimeState.Monster target=s.monsters().get(0);m.tap(v);m.contact(v);SkillVfxRenderer fx=m.h.field(v,"skillVfx");String kind=id.endsWith("017")?"SLEEP":"POISON";assertTrue(fx.statusFx.active(target.id,kind));assertFalse(fx.pulses.stream().anyMatch(p->p.id.equals(id)));int hp=target.hp;s.tick(1.01f);assertEquals(kind.equals("POISON"),target.hp<hp);m.h.capture(v,"v249-persistent-"+kind+"-first");s.tick(.31f);m.h.capture(v,"v249-persistent-"+kind+"-next");RuntimeCombatPortAdapter port=m.h.field(m.h.field(v,"combatSession"),"port");
   if(kind.equals("SLEEP")){port.applyDamage("player",target.id,RuntimeCombatSession.playerAttackActionId(AnimationAction.THRUST),1);assertFalse(fx.statusFx.active(target.id,kind));}
   else{port.abilities.apply(target.id,"SK_성직자_008");assertFalse(fx.statusFx.active(target.id,kind));s.skillEffects().put(target.id,id,kind,1,.1f);s.tick(.2f);assertFalse(fx.statusFx.active(target.id,kind));}
   s.skillEffects().put(target.id,id,kind,1,10);target.alive=false;fx.statusFx.draw(new Canvas(Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888)),m.h.field(v,"skillAnchors"));s.tick(.01f);assertFalse(fx.statusFx.active(target.id,kind));
  }
 }
