 @Test public void dilumeniAndSorumaAreExactMartialRecipientAliasesWithSameRegistrationAndRealStatus()throws Exception{
  ClassicSkillReference ref=new ClassicSkillReference(m.h.c);for(String[] pair:new String[][]{{"SK_마법사_023","SK_무도가_010","BLIND"},{"SK_마법사_025","SK_무도가_018","FREEZE"}}){assertSame(ref.channel(pair[1],false),ref.channel(pair[0],false));assertNull(ref.channel(pair[0],true));SkillVfxRenderer aa=new SkillVfxRenderer(m.h.c,new SkillPresentationCatalog(m.h.c)),bb=new SkillVfxRenderer(m.h.c,new SkillPresentationCatalog(m.h.c));SkillVfxRenderer.Anchors anchor=new SkillVfxRenderer.Anchors(){public float x(String id){return 300;}public float y(String id){return 300;}};for(float age:new float[]{.01f,.12f,.25f}){aa.pulses.clear();bb.pulses.clear();SkillVfxRenderer.Pulse pa=new SkillVfxRenderer.Pulse(1,pair[0],"classic",0,"monster",false,1,300,300),pb=new SkillVfxRenderer.Pulse(1,pair[1],"classic",0,"monster",false,1,300,300);pa.age=pb.age=age;aa.pulses.add(pa);bb.pulses.add(pb);Bitmap ba=Bitmap.createBitmap(600,600,Bitmap.Config.ARGB_8888),bc=ba.copy(Bitmap.Config.ARGB_8888,true);aa.draw(new Canvas(ba),anchor);bb.draw(new Canvas(bc),anchor);assertTrue(pair[0]+" exact recipient registration",ba.sameAs(bc));ba.recycle();bc.recycle();}m.setup();GameView v=m.actor(pair[0]);RuntimeState s=m.h.field(v,"state");m.tap(v);m.contact(v);assertTrue(s.skillEffects().has(s.monsters().get(0).id,pair[2]));m.h.capture(v,"v249-martial-alias-"+pair[2]);}
 }
 @Test public void everyClassAzitoFromRegionalTempleAndInnArrivesMillesInnPersistsAndExitsCorrectly()throws Exception{
  for(String id:new String[]{"SK_성직자_050","SK_마법사_055","SK_무도가_034"})for(String from:new String[]{"MAP_DEATH_UNDER_A","milles_interior_temple_seo","abel_interior_inn"}){m.setup();GameView v=m.actor(id);RuntimeState s=m.h.field(v,"state");SkillAbilityCatalog.Ability ability=SkillAbilityCatalog.get(id);s.rpg().restoreJobCode(ability.job.equals("성직자")?"CLERIC":ability.job.equals("무도가")?"MARTIAL_ARTIST":"MAGE");if(from.startsWith("MAP_"))m.h.call(v,"changeCampaignMap",new Class<?>[]{String.class,boolean.class},from,false);else m.h.call(v,"enterTownInterior",new Class<?>[]{TownInteriorDef.class},TownInteriorDef.forMap(from));s.player().mp=50000;int gold=s.rpg().gold().intValue();SkillBook b=m.h.field(v,"skillBook");m.h.call(v,"useBookSkill",new Class<?>[]{SkillBook.Entry.class},b.get(id));RuntimeCombatSession session=m.h.field(v,"combatSession");m.h.call(v,"tickSkillCombat",new Class<?>[]{float.class},session.effectiveCastSeconds(id)+.01f);assertEquals(id+" from"+from,"milles_interior_inn",s.currentMapId());assertEquals(gold,s.rpg().gold().intValue());assertEquals(50000-session.effectiveMpCost(id),s.player().mp);v.pause();F5mSaveStore.install(m.h.c);GameView restored=new GameView(m.h.c);assertEquals("milles_interior_inn",((RuntimeState)m.h.field(restored,"state")).currentMapId());m.h.call(restored,"leaveReagentShop",new Class<?>[]{});RuntimeState rs=m.h.field(restored,"state");assertEquals(WorldDef.ID,rs.currentMapId());assertTrue(Math.hypot(rs.player().x-2016,rs.player().y-736)<100);}
 }
 @Test public void removedSkillsAreAbsentFromListsQuickslotsAndOldSaveRestore()throws Exception{
  SkillBook book=SkillBook.load(m.h.c);JSONObject saved=book.snapshot();for(String id:new String[]{"SK_마법사_054","SK_성직자_059","SK_마법사_022","SK_마법사_038"}){assertTrue(SkillPolicyV227.retired(id));assertFalse(book.learn(id,100));assertFalse(book.previewable(id));assertFalse(SkillAbilityCatalog.get(id).supported());assertFalse(book.list(true,false).stream().anyMatch(e->e.id.equals(id)));saved.getJSONObject("learned").put(id,100);saved.getJSONArray("slots").put(0,id);assertTrue(book.restore(saved));assertFalse(book.learned(id));assertTrue(book.snapshot().getJSONArray("slots").isNull(0));}
 }
 @Test public void allCatalogDefinitionsAndVisualRoutesAreAuditedWithoutCallingFallbackOriginal()throws Exception{
  SkillBook book=SkillBook.load(m.h.c);SkillPresentationCatalog presentation=new SkillPresentationCatalog(m.h.c);ClassicSkillReference classic=new ClassicSkillReference(m.h.c),shared=new ClassicSkillReference(m.h.c,"shared"),rogue=new ClassicSkillReference(m.h.c,"rogue"),warrior=new ClassicSkillReference(m.h.c,"warrior");CapturedSkillFx captured=new CapturedSkillFx(m.h.c);JSONArray rows=new JSONArray();
  for(SkillBook.Entry e:book.entries()){SkillAbilityCatalog.Ability a=SkillAbilityCatalog.get(e.id);SkillActionContract.Rule rule=SkillActionContract.get(e.id);SkillPresentationCatalog.Entry p=presentation.get(e.id);String source=classic.has(e.id)?"CLASSIC_SOURCE":rogue.has(e.id)?"ROGUE_SOURCE":warrior.has(e.id)?"WARRIOR_SOURCE":shared.has(e.id)?"SHARED_SOURCE":captured.get(e.id)!=null?"CAPTURE":p!=null&&!p.target.equals("NONE")?"PROJECT_FALLBACK":"NONE";if(e.id.equals("SK_마법사_017"))source="PREVIEW_PENDING_SOURCE_V251";if(e.id.equals("SK_마법사_012"))source="PERSISTENT_STATUS_V249";if(SkillVfxRenderer.semeliaCross(e.id))source="SEMELIA_SOURCE_FOUR_DIRECTIONS_V251";
   rows.put(new JSONObject().put("id",e.id).put("name",e.name).put("job",e.job).put("retired",SkillPolicyV227.retired(e.id)).put("runtimeDefinition",e.runtime!=null).put("abilityDefined",a!=null).put("supported",a!=null&&a.supported()).put("kind",a==null?"":a.kind).put("status",a==null?"":a.status).put("rule",rule==null?"MISSING":rule.mode+"/"+rule.pattern).put("effect",source));
  }File out=new File("build/reports/device-review/v249-skill-audit.json");out.getParentFile().mkdirs();try(FileOutputStream stream=new FileOutputStream(out)){stream.write(new JSONObject().put("scope","Static runtime registry reachability; not every skill device tested or original visual accepted").put("skills",rows).toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}assertTrue(rows.length()>200);
 }
